import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict(side, price, qty, arrival, active)
    arrival_counter = 0

    for order in orders:
        op = order[0]

        if op == 'cancel':
            _, oid = order
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if op == 'limit':
            _, oid, side, price, qty = order
        elif op == 'ioc':
            _, oid, side, price, qty = order
        elif op == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        arrival = arrival_counter
        arrival_counter += 1

        remaining = qty
        info = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True, 'type': op}
        book[oid] = info

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_arrival, top_id = sell_heap[0]
                top_info = book.get(top_id)
                if top_info is None or not top_info['active'] or top_info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if op != 'market' and top_price > price:
                    break
                heapq.heappop(sell_heap)
                trade_qty = min(remaining, top_info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                top_info['qty'] -= trade_qty
                if top_info['qty'] > 0:
                    heapq.heappush(sell_heap, (top_price, top_arrival, top_id))
                else:
                    top_info['active'] = False

            info['qty'] = remaining
            if op == 'limit' and remaining > 0:
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                info['active'] = False

        else:  # side == 'sell'
            while remaining > 0 and buy_heap:
                neg_price, top_arrival, top_id = buy_heap[0]
                top_price = -neg_price
                top_info = book.get(top_id)
                if top_info is None or not top_info['active'] or top_info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if op != 'market' and top_price < price:
                    break
                heapq.heappop(buy_heap)
                trade_qty = min(remaining, top_info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                top_info['qty'] -= trade_qty
                if top_info['qty'] > 0:
                    heapq.heappush(buy_heap, (neg_price, top_arrival, top_id))
                else:
                    top_info['active'] = False

            info['qty'] = remaining
            if op == 'limit' and remaining > 0:
                heapq.heappush(sell_heap, (price, arrival, oid))
            else:
                info['active'] = False

    return trades

